add_filter( 'woocommerce_register_shop_order_post_statuses', 'perfectpixel_register_custom_order_status' );
add_filter( 'wc_order_statuses', 'perfectpixel_add_custom_order_status' );
add_filter( 'bulk_actions-edit-shop_order', 'perfectpixel_custom_status_bulk_action', 30 );
add_filter( 'bulk_actions-woocommerce_page_wc-orders', 'perfectpixel_custom_status_bulk_action', 30 );

function perfectpixel_custom_status_key() {
	return 'wc-' . substr( sanitize_key( '{{custom_status_slug}}' ), 0, 17 );
}

function perfectpixel_register_custom_order_status( $statuses ) {
	$statuses[ perfectpixel_custom_status_key() ] = array(
		'label'                     => '{{custom_status_label}}',
		'public'                    => false,
		'exclude_from_search'       => false,
		'show_in_admin_all_list'    => true,
		'show_in_admin_status_list' => true,
		/* translators: %s: number of orders */
		'label_count'               => _n_noop( '{{custom_status_label}} <span class="count">(%s)</span>', '{{custom_status_label}} <span class="count">(%s)</span>' ),
	);
	return $statuses;
}

function perfectpixel_add_custom_order_status( $statuses ) {
	$new = array();
	foreach ( $statuses as $key => $label ) {
		$new[ $key ] = $label;
		if ( 'wc-processing' === $key ) {
			$new[ perfectpixel_custom_status_key() ] = '{{custom_status_label}}'; // Right after "Processing".
		}
	}
	return $new;
}

function perfectpixel_custom_status_bulk_action( $actions ) {
	$actions[ 'mark_' . substr( perfectpixel_custom_status_key(), 3 ) ] = 'Αλλαγή σε «{{custom_status_label}}»';
	return $actions;
}
